export function protectIntentDeletion(
  intent: SendIntent,
  id: string,
): SendIntent {
  if (
    intent.message.id ||
    intent.acceptanceHistoryOnly ||
    intent.deletedIds?.includes(id)
  )
    return intent;
  const deletedIds = intent.deletedIds ?? [];
  return deletedIds.length < 256
    ? { ...intent, deletedIds: [...deletedIds, id] }
    : { ...intent, acceptanceHistoryOnly: true };
}

/** Settle a send against the same cache, deletion, and intent rules as history. */
export function completeSendIntentState(
  state: ConversationCacheState,
  conversation: Conversation,
  clientId: string,
  next: ChatMessage | null,
  now = Date.now(),
) {
  const key = convKey(conversation);
  const intent = state.intents[clientId];
  if (!intent) {
    return next?.id
      ? {
          deleted: boundedConversationMap(
            state.deleted,
            key,
            [...(state.deleted[key] ?? []), next.id].slice(-256),
          ),
        }
      : {};
  }
  const intents = { ...state.intents };
  if (
    next &&
    (messageExpired(next, now) ||
      (next.id &&
        (state.deleted[key]?.includes(next.id) ||
          intent.deletedIds?.includes(next.id))))
  ) {
    delete intents[clientId];
    return {
      intents,
      messages: state.messages[key]
        ? {
            ...state.messages,
            [key]: state.messages[key].filter(
              (message) =>
                message.clientId !== clientId && message.id !== next.id,
            ),
          }
        : state.messages,
    };
  }
  const existing = next?.id
    ? state.messages[key]?.find((message) => message.id === next.id)
    : undefined;
  const resolved = next
    ? {
        ...next,
        delivery:
          existing?.delivery === "delivered"
            ? ("delivered" as const)
            : next.delivery,
        deliveryObservation:
          existing?.delivery === "delivered" || next.delivery === "delivered"
            ? undefined
            : (existing?.deliveryObservation ?? next.deliveryObservation),
        ...(next.file && existing?.file && !existing.metadataPending
          ? { file: existing.file, metadataPending: false }
          : {}),
      }
    : null;
  if (resolved)
    intents[clientId] = {
      ...intent,
      message: resolved,
      onAccepted: resolved.id ? undefined : intent.onAccepted,
      payload:
        resolved.id && resolved.protection
          ? intent.payload.kind === "text"
            ? { ...intent.payload, text: "" }
            : intent.payload.kind === "file"
              ? { ...intent.payload, path: "" }
              : intent.payload
          : intent.payload,
    };
  else delete intents[clientId];
  // Completion must not repopulate an evicted conversation's cache.
  const messages = { ...state.messages };
  if (messages[key]) {
    const rows = messages[key].filter(
      (message) =>
        message.clientId !== clientId && (!next?.id || message.id !== next.id),
    );
    messages[key] =
      resolved && !(resolved.id && intent.acceptanceHistoryOnly)
        ? [...rows, resolved]
        : rows;
  }
  return { intents, messages };
}

/** Exact event ID only. Never associate identical content, paths or filenames. */
export function reconcileMessages(
  history: ChatMessage[],
  previous: ChatMessage[],
  intents: SendIntent[],
  deleted: string[],
  now = Date.now(),
): ChatMessage[] {
  const tombstones = new Set(deleted);
  const overlays = intents
    .filter((i) => !i.acceptanceHistoryOnly || !i.message.id)
    .map((i) => i.message);
  const known = [...previous, ...intents.map((i) => i.message)];
  const result: ChatMessage[] = history
    .filter((m) => !messageExpired(m, now) && (!m.id || !tombstones.has(m.id)))
    .map((m) => {
      const old = m.id ? known.find((p) => p.id === m.id) : undefined;
      return {
        ...m,
        receivedAt: old?.receivedAt ?? m.receivedAt,
        arrivalKind: old?.arrivalKind ?? m.arrivalKind,
        clientId: old?.clientId,
        delivery: old?.delivery,
        deliveryObservation:
          old?.delivery === "awaiting" ? old.deliveryObservation : undefined,
        pending: false,
        metadataPending: false,
      };
    });
  for (const m of overlays) {
    if (messageExpired(m, now) || (m.id && tombstones.has(m.id))) continue;
    if (!m.id || !result.some((h) => h.id === m.id)) result.push(m);
  }
  return result;
}

export function applyProjection(
  message: ChatMessage,
  statuses: Map<string, "awaiting" | "delivered">,
  observations = new Map<string, ChatMessage["deliveryObservation"]>(),
): ChatMessage {
  if (!message.fromMe || !message.id) return message;
  const projected = statuses.get(message.id);
  return {
    ...message,
    delivery: message.delivery === "delivered" ? "delivered" : projected,
    deliveryObservation:
      message.delivery !== "delivered" &&
      projected === "awaiting" &&
      !message.recalled &&
      !message.pending &&
      !message.failed
        ? observations.get(message.id)
        : undefined,
  };
}

/** Keep the active Conversation while bounding message and reaction caches. */
function evictCaches(
  messages: Record<string, ChatMessage[]>,
  reactions: Record<string, ReactionInfo[]>,
  order: string[],
  keep: string,
) {
  const inactive = order.filter((key) => key !== keep);
  const sizes = new Map(
    inactive.map((key) => [
      key,
      retainedPayloadBytes(messages[key]) +
        retainedPayloadBytes(reactions[key]),
    ]),
  );
  let bytes = [...sizes.values()].reduce((sum, size) => sum + size, 0);
  let count = order.length;
  const evicted = new Set<string>();
  for (const key of inactive) {
    if (count <= CONV_CACHE_LIMIT && bytes <= INACTIVE_CONVERSATION_BYTES)
      break;
    evicted.add(key);
    count--;
    bytes -= sizes.get(key) ?? 0;
  }
  if (!evicted.size) return { messages, reactions, order };
  const nextMessages: Record<string, ChatMessage[]> = {};
  for (const key of Object.keys(messages))
    if (!evicted.has(key)) nextMessages[key] = messages[key];
  const nextReactions: Record<string, ReactionInfo[]> = {};
  for (const key of Object.keys(reactions))
    if (!evicted.has(key)) nextReactions[key] = reactions[key];
  return {
    messages: nextMessages,
    reactions: nextReactions,
    order: order.filter((key) => !evicted.has(key)),
  };
}

export function openConversationState(
  state: ConversationCacheState,
  conversation: Conversation,
  target: SearchTarget | undefined,
  request: number,
) {
  const key = convKey(conversation);
  const order = [...state.cacheOrder.filter((item) => item !== key), key];
  const trimmed = evictCaches(state.messages, state.reactions, order, key);
  const retained = new Set(trimmed.order);
  return {
    active: conversation,
    searchTarget: target ? { ...target, key, request } : null,
    historyError: null,
    activeRequest: request,
    members: [],
    channelOwner: "",
    messages: trimmed.messages,
    reactions: trimmed.reactions,
    cacheOrder: trimmed.order,
    historyLimits: Object.fromEntries(
      Object.entries(state.historyLimits).filter(([key]) => retained.has(key)),
    ),
    historyRequests: Object.fromEntries(
      Object.entries(state.historyRequests).filter(([item]) =>
        retained.has(item),
      ),
    ),
    deleted: Object.fromEntries(
      Object.entries(state.deleted).filter(([item]) => retained.has(item)),
    ),
  };
}

export function deleteConversationMessage(
  state: ConversationCacheState,
  key: string,
  target: string,
) {
  return {
    deleted: boundedConversationMap(
      state.deleted,
      key,
      [...(state.deleted[key] ?? []), target].slice(-256),
    ),
    historyRequests: boundedConversationMap(
      state.historyRequests,
      key,
      (state.historyRequests[key] ?? 0) + 1,
    ),
    intents: Object.fromEntries(
      Object.entries(state.intents)
        .filter(
          ([, intent]) =>
            convKey(intent.conversation) !== key ||
            intent.message.id !== target,
        )
        .map(([id, intent]) => [
          id,
          convKey(intent.conversation) === key
            ? protectIntentDeletion(intent, target)
            : intent,
        ]),
    ),
    messages: state.messages[key]
      ? {
          ...state.messages,
          [key]: state.messages[key].filter((message) => message.id !== target),
        }
      : state.messages,
  };
}

export function clearConversationMessages(
  state: ConversationCacheState,
  key: string,
) {
  return {
    deleted: boundedConversationMap(
      state.deleted,
      key,
      [
        ...new Set([
          ...(state.deleted[key] ?? []),
          ...(state.messages[key] ?? []).flatMap((message) =>
            message.id ? [message.id] : [],
          ),
        ]),
      ].slice(-256),
    ),
    historyRequests: boundedConversationMap(
      state.historyRequests,
      key,
      (state.historyRequests[key] ?? 0) + 1,
    ),
    intents: Object.fromEntries(
      Object.entries(state.intents).filter(
        ([, intent]) => convKey(intent.conversation) !== key,
      ),
    ),
    messages: state.messages[key]
      ? { ...state.messages, [key]: [] }
      : state.messages,
  };
}

/** Presentation expiry is synchronous; the core independently erases durable data. */
export function messageExpired(message: ChatMessage, now: number): boolean {
  return message.expiresAtMs != null && message.expiresAtMs <= now;
}

export function expireConversationMessages(
  state: ConversationCacheState,
  now: number,
): Partial<ConversationCacheState> {
  let messages = state.messages;
  let reactions = state.reactions;
  for (const [key, rows] of Object.entries(state.messages)) {
    const expired = new Set(
      rows.filter((m) => messageExpired(m, now)).map((m) => m.id),
    );
    if (!expired.size) continue;
    if (messages === state.messages) messages = { ...messages };
    messages[key] = rows.filter((m) => !messageExpired(m, now));
    if (reactions[key]?.some((r) => expired.has(r.target))) {
      if (reactions === state.reactions) reactions = { ...reactions };
      reactions[key] = reactions[key].filter((r) => !expired.has(r.target));
    }
  }
  const expiredIntents = Object.keys(state.intents).filter((id) =>
    messageExpired(state.intents[id].message, now),
  );
  let intents = state.intents;
  if (expiredIntents.length) {
    intents = { ...intents };
    for (const id of expiredIntents) delete intents[id];
  }
  return { messages, reactions, intents };
}
