import { DeliveryDetails } from "./DeliveryDetails";
import { useAuth } from "@/store/auth";
import { Check, Copy, Inbox, Timer } from "lucide-react";
import { MessageStatus } from "./MessageStatus";
import { useChat } from "@/store/chat";
import { useTranslation } from "react-i18next";
import { formatTime } from "@/lib/format";
import type { ChatMessage } from "@/store/chat";

/** Automatic receipt means the card reached its exact target, not download/read. */
export function DeliveryFooter({
  message,
  isChannel,
  isPersonal = false,
  showTime = true,
}: {
  message: ChatMessage;
  isChannel: boolean;
  isPersonal?: boolean;
  showTime?: boolean;
}) {
  const { t } = useTranslation();
  // A different message, conversation or session owns a fresh, closed disclosure.
  const authScope = useAuth((s) => `${s.user?.id ?? ""}:${s.generation}`);
  const chatScope = useChat(
    (s) => `${s.runEpoch}:${s.identityEpoch}:${s.active?.kind}:${s.active?.id}`,
  );
  const detailsKey = `${authScope}:${chatScope}:${message.id}:${message.clientId}`;
  const clock = useChat((state) =>
    message.expiresAtMs == null ? 0 : state.expiryNow,
  );
  const seconds =
    message.expiresAtMs == null
      ? null
      : Math.max(
          0,
          Math.ceil((message.expiresAtMs - Math.max(clock, Date.now())) / 1000),
        );
  const remaining =
    seconds == null
      ? ""
      : `${Math.floor(seconds / 60)}:${String(seconds % 60).padStart(2, "0")}`;
  const delayed =
    !message.fromMe &&
    message.arrivalKind === "catch_up" &&
    message.receivedAt !== undefined;
  const receiptDetail = delayed
    ? t("conversation.receivedLocally", {
        time: new Date(message.receivedAt!).toLocaleString(),
      })
    : undefined;
  const delivery =
    message.fromMe &&
    !isChannel &&
    !isPersonal &&
    !message.pending &&
    !message.failed &&
    !message.recalled &&
    !!message.id
      ? message.delivery
      : undefined;
  const label = delivery
    ? t(
        `message.delivery.${message.file ? (delivery === "delivered" ? "fileDelivered" : "fileAwaiting") : delivery}`,
      )
    : "";
  const detail = delivery
    ? t(`message.delivery.${message.file ? "fileHelp" : "help"}`)
    : "";
  const custody =
    message.fromMe &&
    isChannel &&
    message.id &&
    !message.file &&
    !message.pending &&
    !message.failed
      ? message.replicas === undefined && message.postOfficeCopies === undefined
        ? "unknown"
        : Math.min(message.replicas ?? 0, 2) ||
          ((message.postOfficeCopies ?? 0) > 0 ? 1 : 0)
      : undefined;
  const postOfficeOnly =
    (message.replicas ?? 0) === 0 && (message.postOfficeCopies ?? 0) > 0;
  const custodyLabel =
    custody === undefined
      ? ""
      : custody === "unknown"
        ? t("message.custody.unknown")
        : postOfficeOnly
          ? t("message.custody.postOffice")
          : t(
              `message.custody.${custody === 0 ? "local" : custody === 1 ? "one" : "multiple"}`,
            );
  const saved =
    isPersonal &&
    message.fromMe &&
    !!message.id &&
    !message.pending &&
    !message.failed;
  if (
    seconds === null &&
    !delayed &&
    !showTime &&
    !message.pending &&
    !delivery &&
    custody === undefined &&
    !saved
  )
    return null;
  return (
    <div
      className={`mt-1 flex w-full min-w-0 max-w-full flex-wrap items-center gap-x-1 gap-y-0.5 px-1 text-[11px] tabular-nums text-muted-foreground ${message.fromMe ? "justify-end" : ""}`}
    >
      {seconds !== null && (
        <span
          data-testid="message-expiry"
          title={t("message.expiresIn", { time: remaining })}
          aria-label={t("message.expiresIn", { time: remaining })}
          className="inline-flex items-center gap-1"
        >
          <Timer className="h-3 w-3" aria-hidden="true" />
          <span>{remaining}</span>
        </span>
      )}
      {delayed && (
        <span
          title={receiptDetail}
          aria-label={receiptDetail}
          data-testid="delayed-message"
        >
          {t("conversation.delayedMessage")}
        </span>
      )}
      {showTime && (
        <span data-testid="message-time">{formatTime(message.wallClock)}</span>
      )}
      {message.pending && <span>{` · ${t("message.sending")}`}</span>}
      {saved && (
        <span data-personal-saved>
          {t(message.file ? "personal.fileCardSaved" : "personal.saved")}
        </span>
      )}
      {delivery === "awaiting" && (
        <DeliveryDetails key={detailsKey} message={message} />
      )}
      {delivery === "delivered" && (
        <MessageStatus
          key={`${detailsKey}:delivered`}
          label={label}
          delivery={delivery}
          icon={<Check className="h-3 w-3" aria-hidden="true" />}
        >
          {() => <p>{detail}</p>}
        </MessageStatus>
      )}
      {custody !== undefined && (
        <MessageStatus
          key={`${detailsKey}:custody:${custody}:${postOfficeOnly}`}
          label={custodyLabel}
          custody={custody}
          icon={
            postOfficeOnly ? (
              <Inbox className="h-3 w-3" aria-hidden="true" />
            ) : (
              <Copy className="h-3 w-3" aria-hidden="true" />
            )
          }
          count={
            custody === "unknown"
              ? "?"
              : !postOfficeOnly && custody > 0
                ? custody === 1
                  ? "1"
                  : "2+"
                : undefined
          }
        >
          {() => (
            <p>
              {t(
                custody === "unknown"
                  ? "message.custody.unknownHelp"
                  : postOfficeOnly
                    ? "message.custody.postOfficeHelp"
                    : "message.custody.help",
              )}
            </p>
          )}
        </MessageStatus>
      )}
      {custody !== undefined &&
        !postOfficeOnly &&
        (message.postOfficeCopies ?? 0) > 0 && (
          <MessageStatus
            key={`${detailsKey}:post-office`}
            label={t("message.custody.postOffice")}
            custody={1}
            icon={<Inbox className="h-3 w-3" aria-hidden="true" />}
          >
            {() => <p>{t("message.custody.postOfficeHelp")}</p>}
          </MessageStatus>
        )}
    </div>
  );
}
import type { ArrivalKind, ReceptionMetadata } from "@/lib/types";

export interface ReceptionEntry {
  /** Core-authenticated recipient event identities for this logical file message. */
  messageAliases?: string[];
  /** Content-free evidence that this external message mentioned the local user. */
  mentioned?: boolean;
  /** Confirmed local removal; never published as a viewed receipt. */
  suppressed?: boolean;
  expiresAtMs?: number;
  seen: boolean;
  late: boolean;
  receivedAt?: number;
  arrivalKind?: ArrivalKind;
}
export type ReceptionLedger = Record<string, Record<string, ReceptionEntry>>;
export interface ConversationReception {
  phase: "idle" | "catching_up" | "waiting";
  received: number;
  batchId?: string;
  checkedAt?: number;
  processing?: boolean;
}
export interface ReceptionState {
  /** Account documents outlive the viewed-entry LRU and may precede history. */
  accountSeen?: Record<string, string[]>;
  ledger: ReceptionLedger;
  overflowUnread: Record<string, number>;
  unreadIds: Record<string, string[]>;
  lateUnreadIds: Record<string, string[]>;
  reception: Record<string, ConversationReception>;
}
export const LEDGER_CONVERSATIONS = 64;
export const LEDGER_IDENTITIES = 1024;
export const LEDGER_TOTAL = 8192;
export const LEDGER_ALIAS_BYTES = 128_000;
const MESSAGE_ALIAS_LIMIT = 64;

export function validMessageAliases(
  value: unknown,
  canonical?: string,
): string[] {
  return Array.isArray(value)
    ? [
        ...new Set(
          value.filter(
            (id): id is string =>
              typeof id === "string" &&
              id !== canonical &&
              validAccountSeenIdentity(id),
          ),
        ),
      ].slice(0, MESSAGE_ALIAS_LIMIT)
    : [];
}

/** Resolve only explicit identities inside this account/conversation's bounded ledger. */
function receptionIdentity(
  entries: Record<string, ReceptionEntry>,
  id: string,
): string {
  if (Object.prototype.hasOwnProperty.call(entries, id)) return id;
  return (
    Object.keys(entries).find((canonical) =>
      entries[canonical].messageAliases?.includes(id),
    ) ?? id
  );
}

/** Immutable conversation maps share their enumeration and unread projections. */
const conversationSnapshots = new WeakMap<
  Record<string, ReceptionEntry>,
  {
    entries: [string, ReceptionEntry][];
    unread: string[];
    late: string[];
  }
>();
function conversationSnapshot(entries: Record<string, ReceptionEntry>) {
  let snapshot = conversationSnapshots.get(entries);
  if (!snapshot) {
    const rows = Object.entries(entries);
    const unread = rows.filter(([, entry]) => !entry.seen && !entry.suppressed);
    snapshot = {
      entries: rows,
      unread: unread.map(([id]) => id),
      late: unread.filter(([, entry]) => entry.late).map(([id]) => id),
    };
    conversationSnapshots.set(entries, snapshot);
  }
  return snapshot;
}

/** Exact identities, scoped to account by persistence. Unread entries retain
 * priority over viewed LRU entries without sorting/cloning the entire ledger. */
export function boundLedger(ledger: ReceptionLedger): ReceptionLedger {
  const ordered = Object.entries(ledger);
  const conversations = ordered
    .filter(([, entries]) => conversationSnapshot(entries).unread.length === 0)
    .concat(
      ordered.filter(
        ([, entries]) => conversationSnapshot(entries).unread.length > 0,
      ),
    )
    .slice(-LEDGER_CONVERSATIONS);
  const retained = new Map<string, [string, ReceptionEntry][]>(
    conversations.map(([key]) => [key, []]),
  );
  let count = 0;
  let aliasBytes = 0;
  // The old stable priority sort visited newest unread entries, then newest
  // viewed entries. Two reverse passes preserve that eviction/alias policy.
  for (const viewed of [false, true]) {
    for (
      let c = conversations.length - 1;
      c >= 0 && count < LEDGER_TOTAL;
      c--
    ) {
      const [key, entries] = conversations[c];
      const rows = conversationSnapshot(entries).entries;
      const kept = retained.get(key)!;
      for (
        let i = rows.length - 1;
        i >= 0 && count < LEDGER_TOTAL && kept.length < LEDGER_IDENTITIES;
        i--
      ) {
        const [id, entry] = rows[i];
        if (Boolean(entry.seen || entry.suppressed) !== viewed) continue;
        let value = entry;
        if (entry.messageAliases !== undefined) {
          const aliases = validMessageAliases(entry.messageAliases, id).filter(
            (alias) => {
              const bytes = JSON.stringify(alias).length + 1;
              if (aliasBytes + bytes > LEDGER_ALIAS_BYTES) return false;
              aliasBytes += bytes;
              return true;
            },
          );
          if (
            !aliases.length ||
            aliases.length !== entry.messageAliases.length ||
            aliases.some(
              (alias, index) => alias !== entry.messageAliases![index],
            )
          ) {
