    [
      ...new Set([
        ...Object.keys(persisted.overflowUnread),
        ...Object.keys(pending.overflowUnread),
      ]),
    ].map((key) => [
      key,
      Math.min(
        1_000_000,
        (persisted.overflowUnread[key] ?? 0) +
          (pending.overflowUnread[key] ?? 0),
      ),
    ]),
  );
