function validEntry(conversation: string, count: unknown): count is number {
  return (
    conversation.length <= 200 &&
    (conversation.startsWith("account:") ||
      conversation.startsWith("channel:")) &&
    Number.isSafeInteger(count) &&
    Number(count) > 0
