pub struct ReceivedDm {
    /// Account-envelope logical ID matching account conversation history.
    /// Legacy device messages have no logical account-message identity.
    pub message_id: Option<EventId>,
    /// Authenticated account-envelope sender, when present.
    pub from_account: Option<String>,
    pub from: UserId,
    pub from_name: String,
    pub text: Vec<u8>,
    pub protection: Option<super::MessageProtection>,
    pub reply_to: Option<EventId>,
}

/// Account material a device receives when it links to an existing device.
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct LinkedAccount {
    pub secret: [u8; 32],
    pub account_id: String,
    pub created_at_ms: Option<u64>,
}

/// A channel summary for listing in the UI.
#[derive(Debug, Clone)]
pub struct ChannelSummary {
    pub id: ConversationId,
    pub name: String,
    pub member_count: usize,
    /// The channel owner's device `user_id` — only the owner may rename the channel or
    /// change its membership. The UI gates the rename action on this.
    pub owner: String,
    /// Restored history from a previous device; this device has no sender key.
    pub archived: bool,
pub struct HistoryEntry {
    /// Authenticated absolute UTC deadline shared by sender and recipient.
    pub expires_at_ms: Option<u64>,
    pub id: EventId,
    /// Author-authenticated per-device manifest aliases for this logical file message.
    pub file_message_aliases: Vec<EventId>,
    pub from_me: bool,
    pub who: String,
    pub text: Vec<u8>,
    pub protection: Option<super::MessageProtection>,
    pub wall_clock: u64,
    pub reply_to: Option<EventId>,
    /// Present when this entry is a file/media message (a `FileManifest` event) rather
    /// than a text message. Carries the metadata the UI needs to render an inline media
    /// bubble or a file card; `text` is empty for a file entry.
    pub file: Option<FileHistoryInfo>,
    /// True when this message was recalled (by its author). The UI renders a placeholder
    /// ("X recalled a message"); `text`/`file` are blanked and never returned.
    pub recalled: bool,
    /// For a message WE recalled, the original text — so the sender can "re-edit" it back
    /// into the composer (WeChat behaviour). `None` for peers' recalls (never expose their
    /// content) and for non-text (file) messages. Only ever set when `recalled` is true.
    pub recalled_text: Option<Vec<u8>>,
    /// An animated-sticker id (emoji codepoint) when this message is a sticker. The UI
    /// renders the bundled animation; `text` holds the fallback emoji char.
    pub sticker: Option<String>,
}

/// File metadata for a [`HistoryEntry`] that represents a file/media message. Lets the
/// UI render media inline (image/video) or a file card, and `read_file`/`save_file` the
/// bytes by `file_conv`.
pub(in crate::node) const CHANNEL_PENDING_BYTES: usize = 8 * 1024 * 1024;

/// A decrypted channel message surfaced to the application. Carries the source
/// event's id + wall-clock and the decoded plaintext body so the node can persist it
/// to the received store (sender-key wire keys are single-use, so history is served
/// from the store, not by re-opening the event).
#[derive(Clone, PartialEq, Eq)]
pub struct ReceivedChannelMessage {
    pub channel_id: ConversationId,
    pub channel_name: String,
    pub from: String,
    pub text: Vec<u8>,
    pub protection: Option<super::MessageProtection>,
    pub reply_to: Option<EventId>,
    pub event_id: EventId,
    pub wall_clock: u64,
    /// The wrapped `MessageBody` plaintext (text + reply_to), for the received store.
    pub(in crate::node) wrapped: Vec<u8>,
    /// Local first successful decryption observation; not persisted in signed events.
    pub received_at: u64,
    pub arrival_kind: &'static str,
    pub own_device: bool,
    pub batch_id: Option<String>,
    pub batch_complete: bool,
    pub batch_size: usize,
    /// Metadata-only batch terminal; never render as a message or count unread.
    pub reception_only: bool,
}

impl std::fmt::Debug for ReceivedChannelMessage {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
//! Legacy standalone SDK file inventory and received-file DTO. Production Node
//! uses the profile-owned indexed projection below; this public in-memory helper
//! retains its original standalone record/lookup contract.

use crate::eventlog::event::{ConversationId, EventId};
use crate::file::AnyManifest;
use std::collections::{HashMap, HashSet};

mod custody_dispatch;
mod historical;
pub(crate) mod indexed;
mod receiving;
mod retention;
pub(crate) mod scopes;
mod work;

/// A received file announcement, surfaced to the application.
#[derive(Debug, Clone)]
pub struct ReceivedFile {
    pub protection: Option<super::MessageProtection>,
    /// Absolute authenticated send-time deadline, if selected.
    pub expires_at_ms: Option<u64>,
    /// The DM/channel conversation the manifest arrived in.
    pub conv: ConversationId,
    /// Whether `conv` names a channel rather than a direct conversation.
    pub is_channel: bool,
    /// The sender's user-id fingerprint.
    pub from: String,
    pub name: String,
    pub size: u64,
    pub mime: String,
    /// The per-file conversation holding the chunk events (pass to `save_file`).
    pub file_conv: ConversationId,
    /// Whether this is inline MEDIA (media button) vs a generic attachment (attach button).
    /// Decided by the sender's intent (manifest kind), not the file extension.
    pub media: bool,
    pub event_id: EventId,
    pub authored_at: u64,
    pub received_at: u64,
    pub arrival_kind: &'static str,
    pub own_device: bool,
    pub batch_id: Option<String>,
    pub batch_complete: bool,
    pub batch_size: usize,
}

#[derive(Default)]
pub struct FileBook {
    manifests: HashMap<ConversationId, AnyManifest>, // keyed by file_conv
    emitted: HashSet<EventId>,
}

impl FileBook {
    pub fn new() -> Self {
        Self::default()
            .reception_effects
            .page(after, through, limit, self.expiry_now())?;
        let mut receipts = Vec::with_capacity(page.rows.len());
        for fact in page.rows {
            let metadata = fact.metadata;
            if fact.source.kind == ReceptionKind::File {
                if let Some(entry) = fact.entry
                    && let Some(file) = self.received_file_for_reception(&entry, &metadata)?
                {
                    receipts.push(HostReception::File(file));
                }
                continue;
            }
            if fact.source.kind == ReceptionKind::DirectMessage {
                let Some(entry) = fact.entry else { continue };
                let envelope = DmEnvelope::decode(&entry.plaintext);
                let (id, account) = envelope
                    .as_ref()
                    .map_or((entry.event_id, None), |envelope| {
                        let peer = if envelope.route.sender_account == self.account_id() {
                            &envelope.route.recipient_account
                        } else {
                            &envelope.route.sender_account
                        };
                        (
                            crate::eventlog::EventId::new(envelope.msg_id),
                            Some(peer.as_str()),
                        )
                    });
                let inner = envelope
                    .as_ref()
                    .map_or(entry.plaintext.as_slice(), |envelope| {
                        envelope.body.as_slice()
                    });
                if self.recipient_expired(inner, id, entry.wall_clock)
                    || self.message_recalled_selected(
                        entry.conversation,
                        id,
                        account,
                        envelope.as_ref().map(|_| entry.from.as_str()),
                    )?
                {
                    continue;
                }
                let body = MessageBody::decode(inner);
                let from_name = self
                    .routing_peer(&metadata.from_device)
                    .map_or_else(|| metadata.from_device.clone(), |peer| peer.name);
                receipts.push(HostReception::DirectMessage(ReceivedDm {
                    message_id: envelope
                        .as_ref()
                        .map(|envelope| crate::eventlog::EventId::new(envelope.msg_id)),
                    from_account: envelope
                        .as_ref()
                        .map(|envelope| envelope.route.sender_account.clone()),
                    from: metadata.from_device,
                    from_name,
                    text: body.text,
                    protection: body.protection,
                    reply_to: body.reply_to,
                }));
                continue;
            }
            let (body, wall_clock) = match fact.entry {
                Some(entry) => {
                    if self.recipient_expired(&entry.plaintext, entry.event_id, entry.wall_clock)
                        || self.message_recalled_selected(
                            entry.conversation,
                            entry.event_id,
                            None,
                            None,
                        )?
                    {
                        continue;
                    }
                    (MessageBody::decode(&entry.plaintext), entry.wall_clock)
                }
                None => (MessageBody::new(Vec::new(), None), 0),
            };
            let channel_name = self
                .channels
                .lock()
                .expect("channels mutex not poisoned")
                .state(&fact.source.conversation)
                .map_or_else(String::new, |state| state.name().to_owned());
            receipts.push(HostReception::ChannelMessage(ReceivedChannelMessage {
                channel_id: fact.source.conversation,
                channel_name,
                from: metadata.from_device,
                text: body.text,
                protection: body.protection,
                reply_to: body.reply_to,
                event_id: fact.source.event_id,
                wall_clock,
                wrapped: Vec::new(),
                received_at: metadata.received_at,
                arrival_kind: match metadata.arrival_kind {
                    ArrivalKind::Live => "live",
                    ArrivalKind::CatchUp => "catch_up",
                    ArrivalKind::HistorySync => "history_sync",
                },
                own_device: metadata.own_device,
                batch_id: metadata.batch_id,
                batch_complete: metadata.batch_complete,
                batch_size: metadata.batch_size,
                reception_only: metadata.reception_only,
            }));
        }
        Ok(HostReceptionPage {
            after,
            next: page.next,
            through: page.through,
            complete: page.complete,
            receipts,
        })
    }
}

#[cfg(test)]
mod tests {
    use super::*;
//! Selected receipt presentation composes the file authority owner. A durable
//! cache row alone cannot authorize a file card after erase, recall or expiry.
use super::*;
use crate::eventlog::LogError;
use crate::node::reception_effects::{ArrivalKind, ReceptionMetadata};

impl Node {
    pub(in crate::node) fn received_file_for_reception(
        &self,
        entry: &ReceivedEntry,
        metadata: &ReceptionMetadata,
    ) -> Result<Option<ReceivedFile>, LogError> {
        {
            let delivery = self.delivery.lock().expect("delivery lock not poisoned");
            if delivery.file_erased(entry.conversation, entry.event_id)
                || delivery.manifest_event_erased(entry.event_id)
            {
                return Ok(None);
            }
        }
        if self.file_message_row_suppressed(entry)?
            || self.recipient_expired(&entry.plaintext, entry.event_id, entry.wall_clock)
        {
            return Ok(None);
        }
        let Some(offer) = self
            .files
            .lock()
            .expect("file book lock not poisoned")
            .offer_for_entry(entry)?
        else {
            return Ok(None);
        };
        let Some(manifest) = validated_manifest(&entry.plaintext) else {
            return Err(LogError::CorruptFile(
                "invalid retained file manifest".into(),
            ));
        };
        let is_channel = self
            .channels
            .lock()
            .expect("channels lock not poisoned")
            .state(&entry.conversation)
            .is_some();
        let (event_id, author_account) = {
            let identities = self
                .file_message_identities
                .lock()
                .expect("file identity lock not poisoned");
            (
                identities.row_logical(entry)?,
                identities.row_author_account(entry)?,
            )
        };
        // Existing DM reception suppresses copies from certified sibling
        // devices; channel/history rows retain explicit own-device metadata.
        if !is_channel && metadata.own_device {
            return Ok(None);
        }
        let account = (!is_channel).then_some(author_account.as_deref()).flatten();
        if self
            .message_recalled_selected(
                entry.conversation,
                event_id,
                account,
                author_account.as_deref(),
            )
            .map_err(|error| match error {
                NodeError::Log(error) => error,
                error => LogError::CorruptFile(format!("file recall observation: {error}")),
            })?
        {
            return Ok(None);
        }
        Ok(Some(ReceivedFile {
            protection: manifest.protection(),
            expires_at_ms: crate::expiry::deadline(&entry.plaintext),
            conv: if is_channel {
                entry.conversation
            } else {
                offer.parent
            },
            is_channel,
            from: metadata.from_device.clone(),
            name: if manifest.protection().is_some() {
                "Protected image".into()
            } else {
                manifest.name().to_owned()
            },
            size: manifest.size(),
            mime: manifest.mime().to_owned(),
            file_conv: manifest.file_conv(),
            media: super::super::media_store::manifest_is_media(&manifest),
            event_id,
            authored_at: entry.wall_clock,
            received_at: metadata.received_at,
            arrival_kind: match metadata.arrival_kind {
                ArrivalKind::Live => "live",
                ArrivalKind::CatchUp => "catch_up",
                ArrivalKind::HistorySync => "history_sync",
            },
            own_device: metadata.own_device,
            batch_id: metadata.batch_id.clone(),
            batch_complete: metadata.batch_complete,
            batch_size: metadata.batch_size,
        }))
    }
}
