    pub(crate) fn received_via(
        &self,
        conversation: ConversationId,
        id: EventId,
    ) -> Result<Option<ReceivedVia>, LogError> {
        self.profile.database().read(|c| {
            self.state_on(c)?;
            // Select the first source row BEFORE joining evidence. An unknown old
            // alias must not acquire a later alias's known ingress.
            let tag: Option<Option<i64>> = c.query_row("SELECT o.via FROM transcript_rows t LEFT JOIN transcript_ingress_origins o ON o.ordinal=t.ordinal AND o.account=?1 WHERE t.kind IN (2,3) AND t.conversation=?2 AND (t.row_key=?3 OR t.logical_id=?3) ORDER BY t.ordinal LIMIT 1", params![self.account.as_slice(),conversation.as_bytes().as_slice(),id.as_bytes().as_slice()], |r| r.get(0)).optional()?;
            tag.flatten().map(ReceivedVia::from_tag).transpose()
        })
    }
}

/// Migrate evidence only for a new reception, in the existing transcript commit.
pub(super) fn project_on(
    c: &Connection,
    account: &[u8; 32],
