import type { Page } from "@playwright/test";

// Successful portable scenarios retain evidence in the full Chromium run.
test.use({ trace: "on" });

async function observeLocalDelivery(page: Page) {
  await page.evaluate(() => {
    const scope = window as unknown as {
      __TAURI_INTERNALS__: {
        invoke: (
          command: string,
          args: Record<string, unknown>,
        ) => Promise<unknown>;
      };
      __deliveryDetailsFixture: {
        observation: { kind: string; age_ms: number; reason?: string } | null;
        hold: boolean;
        entered: boolean;
        seenKind: string | null;
        release: () => void;
      };
    };
    const state = {
      observation: {
        kind: "retry_scheduled",
        age_ms: 180000,
        reason: "post_office_disabled",
      } as {
        kind: string;
        age_ms: number;
        reason?: string;
      } | null,
      hold: false,
      entered: false,
      seenKind: null as string | null,
      release: () => {},
    };
    scope.__deliveryDetailsFixture = state;
    const original = scope.__TAURI_INTERNALS__.invoke;
    scope.__TAURI_INTERNALS__.invoke = async (command, args) => {
      const result = await original(command, args);
      if (command !== "owner_delivery_statuses") return result;
      state.seenKind = state.observation?.kind ?? null;
      const rows = (result as Array<{ id: string; status: string }>).map(
        (row) => ({
          ...row,
          ...(row.status === "awaiting" && state.observation
            ? { observation: state.observation }
            : {}),
        }),
      );
      if (!state.hold) return rows;
      state.entered = true;
      return new Promise((resolve) => {
        state.release = () => resolve(rows);
      });
    };
  });
}

import { defineConfig, devices } from "@playwright/test";
import { createHash } from "node:crypto";

const worktreePort =
  5200 +
  (parseInt(
    createHash("sha256").update(process.cwd()).digest("hex").slice(0, 4),
    16,
  ) %
    1000);
const port = Number(
  process.env.MESH_TALK_E2E_PORT ?? (process.env.CI ? 5173 : worktreePort),
);
// Keep browser navigation and server binding on the same address family.
const url = `http://127.0.0.1:${port}`;

// Browser E2E for the Mesh-Talk UI. Runs the Vite dev server + drives the real React app in
// headless Chromium with a mocked Tauri IPC layer (see e2e/tauri-mock.ts).
export default defineConfig({
  testDir: "./e2e",
  // A functional journey includes cold transforms, rendering and several
  // successful state assertions. Use the existing Windows/coverage watchdog
  // across platforms; individual assertion and product deadlines stay separate.
  timeout: 90_000,
  fullyParallel: true,
  forbidOnly: !!process.env.CI,
  retries: process.env.CI ? 1 : 0,
  // A single macOS worker avoids Vite asset decode retries and page-load
  // timeouts seen in the full suite with four concurrent browsers. CI already
  // uses one; Windows keeps its existing four-worker limit.
  workers:
    process.env.CI || process.platform === "darwin"
      ? 1
      : process.platform === "win32"
        ? 4
        : undefined,
  reporter: process.env.CI ? "list" : "html",
  snapshotPathTemplate: "e2e/{testFileName}-snapshots/{arg}{ext}",
  expect: {
    toHaveScreenshot: {
      maxDiffPixelRatio: 0.015,
    },
  },
  use: {
    baseURL: url,
    timezoneId: "Asia/Tokyo",
    trace: "retain-on-failure",
  },
  projects: [{ name: "chromium", use: { ...devices["Desktop Chrome"] } }],
  webServer: {
    command: `npm run dev -- --host 127.0.0.1 --port ${port}`,
    env: { MESH_TALK_E2E: "1" },
    url,
    // Another worktree may already have Vite on this port. Reusing it can
    // silently test an older checkout and report a false pass or failure.
    reuseExistingServer: false,
    timeout: 120_000,
  },
});

