  Object.assign(globalThis, { IS_REACT_ACT_ENVIRONMENT: true });
  await i18n.changeLanguage("en");
  const host = document.createElement("div");
  document.body.append(host);
  const root = createRoot(host);
  const original: ChatMessage = { ...base, fromMe: false, receivedVia: "member", arrivalKind: "catch_up", receivedAt: 42 };
  const show = (message: ChatMessage) => act(async () => root.render(createElement(DeliveryFooter, { message, isChannel: true })));
  const trigger = () => host.querySelector<HTMLButtonElement>('[data-testid="message-source-trigger"]')!;
  try {
    await show(original);
    expect(host.querySelector('[data-testid="message-time"]')).not.toBeNull();
    expect(host.querySelector('[data-testid="delayed-message"]')).not.toBeNull();
    await act(async () => trigger().click());
    const panel = host.querySelector<HTMLElement>('[data-testid="message-source"]')!;
    expect(panel.textContent).toContain("not describe the full route");
    await act(async () => panel.dispatchEvent(new KeyboardEvent("keydown", { key: "Escape", bubbles: true })));
    expect(trigger().getAttribute("aria-expanded")).toBe("false");
    expect(document.activeElement).toBe(trigger());
    for (const replacement of [
      { ...original, receivedVia: "sender" as const },
      { ...original, id: "another-message" },
    ]) {
      await act(async () => trigger().click());
      await show(replacement);
      expect(host.querySelector('[data-testid="message-source"]')).toBeNull();
      await show(original);
    }
    const savedActive = useChat.getState().active;
    const savedGeneration = useAuth.getState().generation;
    try {
      for (const invalidate of [
        () => useChat.setState({ active: { kind: "channel", id: "other", name: "Other" } }),
        () => useAuth.setState((state) => ({ generation: state.generation + 1 })),
      ]) {
        await act(async () => trigger().click());
        await act(async () => invalidate());
        expect(host.querySelector('[data-testid="message-source"]')).toBeNull();
      }
    } finally {
      await act(async () => {
        useChat.setState({ active: savedActive });
        useAuth.setState({ generation: savedGeneration });
      });
    }
    await show({ ...original, announcement: { revision: "r", content: "notice", author: "owner", authored_at: 1 } });
    expect(host.querySelector('[data-testid="message-source-trigger"]')).toBeNull();
  } finally {
    await act(async () => root.unmount());
    host.remove();
  }
});
EOF
