test("linked-device channel history waits for copy confirmation before showing a check", async ({
  page,
}) => {
  await enterChat(page);
  await page.evaluate(() => {
    const scope = window as unknown as {
      __TAURI_INTERNALS__: {
        invoke(
          command: string,
          args: Record<string, unknown>,
        ): Promise<unknown>;
      };
      __linkedCopyConfirmed: boolean;
    };
    const original = scope.__TAURI_INTERNALS__.invoke;
    scope.__linkedCopyConfirmed = false;
    scope.__TAURI_INTERNALS__.invoke = async (command, args) => {
      if (command === "channel_custody_statuses")
        return scope.__linkedCopyConfirmed
          ? [{ id: "sibling-authored", replicas: 1, post_offices: 0 }]
          : [];
      if (command === "channel_history") {
        const history = (await original(command, args)) as unknown[];
        return [
          ...history,
          {
            id: "sibling-authored",
            from_me: true,
            who: "device_linked_sibling",
            text: "Group message synced from my linked device",
            wall_clock: 1_700_000_200_000,
            reply_to: null,
          },
        ];
      }
      return original(command, args);
    };
  });
  await page.getByTestId("conversation-row-chan_team_dddd4444").click();
  const bubble = page
    .getByTestId("message-bubble")
    .filter({ hasText: "Group message synced from my linked device" });
  await expect(bubble.locator('[data-custody="unknown"]')).toBeVisible();
  await expect(bubble.locator("[data-custody]")).toHaveAccessibleName(
    "Copy status unavailable",
  );
  await expect(bubble).not.toContainText("No member copy confirmed");
  await expect(bubble).not.toContainText("✓");
  await expect(bubble.locator("[data-delivery]")).toHaveCount(0);
  await bubble.locator("[data-custody]").focus();
  await expect(bubble.getByTestId("message-status")).toHaveCount(0);
  await bubble.locator("[data-custody]").press("Enter");
  await expect(bubble.getByTestId("message-status")).toContainText(
    "Another linked device may have newer information.",
  );
  await page.evaluate(() => {
import { sourceIdentity } from "../../../scripts/evals/source-identity.mjs";
import { writeFile } from "node:fs/promises";
import { test as mocked, expect } from "../tauri-mock";
import {
  installBrowserErrorDetails,
  readBrowserErrorDetails,
} from "./browser-error-details";

export function requireNoUncaughtBrowserErrors(errors: readonly string[]) {
  expect(errors, "uncaught React/browser errors").toEqual([]);
}

// Browser evidence only: this fixture never starts the Rust/Tauri runtime.
export const test = mocked.extend<{ portableEvidence: void }>({
  portableEvidence: [
    async ({ page, browserName }, provide, testInfo) => {
      const errors: string[] = [];
      let fixtureFailed = false;
      let fixtureError: string | undefined;
      let screenshotError: string | undefined;
      const sourceSha = sourceIdentity();
      // Portable scenarios are offline and must not depend on the public catalog.
      // WebKit reports failed cross-origin catalog requests as page errors.
      await page.route("**/marketplace/catalog.json", (route) =>
        route.fulfill({
          contentType: "application/json",
          headers: { "access-control-allow-origin": "*" },
          body: JSON.stringify({ schemaVersion: 1, packs: [] }),
        }),
      );
      page.on("pageerror", (error) => errors.push(error.message));
      try {
        await installBrowserErrorDetails(page);
        expect(sourceSha).toMatch(/^[a-f0-9]{40}$/);
        if (process.env.EVAL_SOURCE_SHA !== undefined)
          expect(
            process.env.EVAL_SOURCE_SHA,
            "evidence source must match actual checkout",
          ).toBe(sourceSha);
        await provide();
        requireNoUncaughtBrowserErrors(errors);
      } catch (error) {
        fixtureFailed = true;
        fixtureError = String(error);
        throw error;
      } finally {
        const screenshotPath = testInfo.outputPath("screenshot.png");
        try {
          await page.screenshot({ path: screenshotPath });
          await testInfo.attach("portable-browser-screenshot", {
            path: screenshotPath,
            contentType: "image/png",
          });
        } catch (error) {
          screenshotError = String(error);
        }
        const evidencePath = testInfo.outputPath("evidence.json");
        const browserErrors = await readBrowserErrorDetails(page);
        if (errors.length) {
